func TestEnumTemplateLocalizationStatus(t *testing.T) {
	t.Run("NewFromString_synced", func(t *testing.T) {
		t.Parallel()
		val, err := NewTemplateLocalizationStatusFromString("synced")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TemplateLocalizationStatus("synced"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_stale", func(t *testing.T) {
		t.Parallel()
		val, err := NewTemplateLocalizationStatusFromString("stale")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TemplateLocalizationStatus("stale"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_syncing", func(t *testing.T) {
		t.Parallel()
		val, err := NewTemplateLocalizationStatusFromString("syncing")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TemplateLocalizationStatus("syncing"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_failed", func(t *testing.T) {
		t.Parallel()
		val, err := NewTemplateLocalizationStatusFromString("failed")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, TemplateLocalizationStatus("failed"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewTemplateLocalizationStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewTemplateLocalizationStatusFromString("synced")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

